def normalise(s):
    out = []
    pending = False
    for c in s:
        if c in "‘’‛′":
            c = "'"
        elif c in "“”‟″":
            c = '"'
        elif "‐" <= c <= "―" or c == "−":
            c = "-"
        elif c == "­":
            continue
        if c.isspace():
            pending = True
            continue
        if pending and out:
            out.append(" ")
        pending = False
        out.append(c)
    return "".join(out)


TEXT = open(SRC_PATH, encoding="utf-8").read()
PIECES = []
LINES = []  # (offset, line)
_off = 0
for _n, _line in enumerate(TEXT.split("\n")):
    _p = normalise(_line)
    if not _p:
        continue
    LINES.append((_off, _n + 1))
    PIECES.append(_p)
    _off += len(_p) + 1
NORM = " ".join(PIECES)


def line_at(offset):
    lo, hi = 0, len(LINES)
    while lo < hi:
        mid = (lo + hi) // 2
        if LINES[mid][0] <= offset:
            lo = mid + 1
        else:
            hi = mid
    return LINES[lo - 1][1] if lo else 1


def position(quote):
